using System;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using OniMcp.Tools;using UnityEngine;
namespace OniMcp.Tools{public static partial class BuildPlanningTools{internal static JObject UnknownParent(JObject args)=>JObject.Parse(JsonConvert.SerializeObject(TryPlanOne(args["prefabId"].Value<string>(),0,0,args),OniMcp.Support.McpJsonUtil.Settings));}}
internal static class FinalUnknownContractRegression{
 private static int checks;private static void Check(bool value,string reason){checks++;if(!value)throw new InvalidOperationException("Final unknown contract: "+reason);}
 private static void Setup(string id="GeometryFixture"){BlueprintCompletionRegression.Setup();BuildPlanningTools.ResetPlannerFixture();DebugHandler.InstantBuildMode=false;WorldEditorTools.FixtureModeRequest=null;WorldEditor.Area=null;UnityEngine.Object.ThrowEnumeration=false;BuildPlanningTools.FixtureGeometryReason=null;BuildPlanningTools.FixtureDefs[id]=new BuildingDef{PrefabID=id,Name=id,BuildLocationRule=BuildLocationRule.Anywhere};BuildPlanningTools.FixtureFacadeValid=true;BuildPlanningTools.FixtureFacadeUnknownReason=null;BuildPlanningTools.FixtureFacadeCalls=0;}
 private static JObject Args(string id)=>new JObject{["prefabId"]=id,["dryRun"]=true,["worldId"]=0,["material"]="Cuprite",["facade"]="CustomFixture"};
 private static JObject Candidate(string id){var a=Args(id);a["domain"]="planning";a["action"]="placement_candidates";a["x1"]=0;a["y1"]=0;a["x2"]=3;a["y2"]=0;a["maxEvaluations"]=2;a["scanOffset"]=1;a["limit"]=2;return JObject.Parse(BuildPlanningTools.FindPlacementCandidates().Handler(a).Content[0].Text);}
 private static void Geometry(){foreach(string reason in new[]{"placement_offsets_missing","geometry_read_failed","native_footprint_mismatch"}){Setup();BuildPlanningTools.FixtureGeometryReason=reason;var a=Args("GeometryFixture");var before=a.DeepClone();var p=BuildPlanningTools.UnknownParent(a);Check((string)p["details"]?["assessmentState"]=="unknown"&&(string)p["details"]?["geometryReasonCode"]==reason,"actual parent preserves producer-defined unavailable native geometry as unknown");Check(p["details"]["nativePlacementValid"].Type==JTokenType.Null&&p["details"]["availableNow"].Type==JTokenType.Null,"geometry unavailability does not fabricate native eligibility");var w=Candidate("GeometryFixture");Check((int)w["unknownCount"]==2&&(int)w["knownRejectedCount"]==0&&(string)w["validation"]["coverage"]=="partial","geometry observation failures are unknown rows, not native-invalid or complete window proof");Check(BuildPlanningTools.FixtureSelectCalls==0&&BuildPlanningTools.FixtureFacadeCalls==0&&BuildTool.Instance.BuildCalls==0&&JToken.DeepEquals(a,before),"unavailable geometry exits before inventory/facade/native work without caller changes");}
 foreach(string reason in new[]{"orientation_invalid","origin_invalid","occupied_cell_invalid"}){Setup();BuildPlanningTools.FixtureGeometryReason=reason;var w=Candidate("GeometryFixture");Check((int)w["unknownCount"]==0&&(int)w["knownRejectedCount"]==2,"genuine request/world/occupied-cell failures remain known "+reason);}}
 private static void QueueFacade(){foreach(bool? unlocked in new bool?[]{null,false}){Setup("GasPermeableMembrane");BuildPlanningTools.FixtureFacadeValid=unlocked??false;BuildPlanningTools.FixtureFacadeUnknownReason=unlocked.HasValue?null:"owned_inventory_cache_missing";foreach(int x in new[]{0,1,2}){var old=new GameObject();old.Add(new BuildingComplete{Def=new BuildingDef{PrefabID="Tile"}});Grid.Objects[Grid.XYToCell(x,0),(int)ObjectLayer.FoundationTile]=old;var queue=new GameObject();queue.Add(new Constructable{SelectedElementsTags=new System.Collections.Generic.List<Tag>{new Tag("Cuprite")}});Grid.Objects[Grid.XYToCell(x,0),(int)ObjectLayer.ReplacementTile]=queue;}
 var a=Args("GasPermeableMembrane");var before=a.DeepClone();var p=BuildPlanningTools.UnknownParent(a);var d=p["details"] as JObject;if(!unlocked.HasValue)Check(d!=null&&(string)d["assessmentState"]=="unknown"&&(string)d["facadeSelection"]?["reasonCode"]=="owned_inventory_cache_missing","early queued replacement facade preserves structured unknown before generic parent guard");BuildPlanningTools.FixtureFacadeCalls=0;var w=Candidate("GasPermeableMembrane");Check((int)w["unknownCount"]==(unlocked.HasValue?0:2)&&(int)w["knownRejectedCount"]==(unlocked.HasValue?2:0),"early queued replacement distinguishes unknown facade from observed locked");Check(BuildPlanningTools.FixtureFacadeCalls==1,"queued-replacement preview shares exactly one request-local facade capture");Check(BuildPlanningTools.FixtureSelectCalls==0&&BuildPlanningTools.FixtureAutoDigCalls==0&&BuildTool.Instance.BuildCalls==0&&JToken.DeepEquals(a,before),"early facade observation adds no material/dig/build/caller mutations");}}
 internal static void Run(string[] args){OniMcp.Support.McpLocalization.LanguageProvider=()=>"en";if(args.Length==0||args[0]=="geometry")Geometry();if(args.Length==0||args[0]=="queue")QueueFacade();Console.WriteLine("Final unknown contract: "+checks+" actual parent/queue-reuse/context/candidate checks PASS (native geometry/facade outcomes supplied; actual facade resolver/DTO tested separately)");}
}
